{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "protocol",
      "alternatives": [
        "(df['proto'] != 'tcp') -> ((df['swin'] == 0) & (df['dwin'] == 0) & (df['stcpb'] == 0) & (df['dtcpb'] == 0) & (np.isclose(df['tcprtt'], 0, atol=1e-9)) & (np.isclose(df['synack'], 0, atol=1e-9)) & (np.isclose(df['ackdat'], 0, atol=1e-9)))",
        "(df['proto'] != 'tcp') -> ((df['sloss'] == 0) & (df['dloss'] == 0))",
        "(df['proto'] != 'tcp') -> (df['state'] == '-')"
      ],
      "features": ["proto", "swin", "dwin", "stcpb", "dtcpb", "tcprtt", "synack", "ackdat", "sloss", "dloss", "state"],
      "rationale": "TCP-specific fields should be zero or unused for non-TCP protocols."
    },
    {
      "id": "R2",
      "category": "protocol",
      "alternatives": [
        "(df['service'] != 'http') -> ((df['trans_depth'] == 0) & (df['response_body_len'] == 0))"
      ],
      "features": ["service", "trans_depth", "response_body_len"],
      "rationale": "HTTP-specific fields should be zero for non-HTTP services."
    },
    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "(df['service'] != 'ftp') -> (df['is_ftp_login'] == 0)"
      ],
      "features": ["service", "is_ftp_login"],
      "rationale": "FTP login flag should be zero for non-FTP services."
    },
    {
      "id": "R4",
      "category": "protocol",
      "alternatives": [
        "(df['proto'] == 'tcp') -> (df['state'] != '-')"
      ],
      "features": ["proto", "state"],
      "rationale": "TCP flows should have a valid state, not the unused marker '-'."
    }
  ]
}
